const a = [1, 2, 3];
const b = [2, 3, 4];
const union = [...new Set([...a, ...b])].sort((x, y) => x - y);
const setB = new Set(b);
const intersection = [...new Set(a)].filter((x) => setB.has(x)).sort((x, y) => x - y);
console.log("union: " + union.join(",") + " intersection: " + intersection.join(","));
